# Scale all sample base volumes by 1.4, cap at 64
s=open('src/gen_samples.py').read()
import re
def scale_vol(line, factor=1.4):
    # matches like: (1,"bass",  bass,  True,  50, 128),
    m=re.search(r'(\(\d+,"[^"]+",\s+\w+,\s+(?:True|False),\s+)(\d+)(,\s+\d+\))', line)
    if m:
        v=int(m.group(2)); nv=min(64,round(v*factor))
        return line.replace(m.group(0), m.group(1)+str(nv)+m.group(3))
    return line
lines=s.split('\n')
out=[]
for ln in lines:
    if re.search(r'\(\d+,"[^"]+",\s+\w+,\s+(True|False),\s+\d+,\s+\d+\)', ln):
        out.append(scale_vol(ln))
    else:
        out.append(ln)
open('src/gen_samples.py','w').write('\n'.join(out))
print("volumes scaled")
PY
